"""Verb-expectation feature for layers.15.mlp.down_proj component 4487.

This component is negative where the text is mid-way through a verb phrase and a
verb (or predicate) is about to follow. Its strongest negative values fall on:
- modal auxiliaries, most on would, shall, might, will and could, less on can, may,
  and least on should and must;
- "make" and its forms (made, making, makes);
- "to" after words like "likely" or "seems", and "not" right after a modal;
- "the" that opens the main clause of "the more X, the better" constructions.
It is mildly negative on subject pronouns (you, it, we, they, he, she), on the forms
of be, have and do, and on words like "then", "still" and "without"; it is mildly
positive on commas. Everything else is near zero. Most of its variation is
context-dependent and no word list captures it, so this explains only about 5% of
the variance.
"""
READS = ()

MODAL_VALUE = {
    "would": -2.0, "shall": -2.0, "might": -1.8, "will": -1.5, "could": -1.5,
    "can": -1.2, "may": -1.3, "should": -0.6, "must": -0.6,
}
MAKE = {"make", "makes", "made", "making"}
PREDICATE_TO = {"likely", "seems", "seem", "lead", "leads", "expected", "tends", "known", "possible"}
SUBJECT_PRONOUNS = {"you", "it", "we", "they", "he", "she"}
AUX = {"is", "are", "be", "was", "were", "been", "has", "have", "had", "do", "does", "did"}
MILD = {"then", "still", "without", "better", "never", "always", "not", "very"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = ""
    if len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    if word in MAKE:
        value = -3.0
    elif word in MODAL_VALUE:
        value = MODAL_VALUE[word]
    elif word == "to":
        value = -0.5 if prev in PREDICATE_TO else 0.0
    elif word == "not" and prev in MODAL_VALUE:
        value = -1.2
    elif word == "the" and prev == ",":
        value = -0.4
    elif word in SUBJECT_PRONOUNS:
        value = -0.3
    elif word in AUX:
        value = -0.2
    elif word in MILD:
        value = -0.4
    elif word == ",":
        value = 0.1
    else:
        value = 0.0
    return carry, value

"""Layer 15, MLP down_proj, hidden unit 4489: a compound-noun-head detector.

In plain terms: the component is positive on a common noun that directly follows
another noun or an adjective, so the noun completes a compound term ("education
system", "T cells", "magnetic field", "MobiKwik wallet", "Python interpreter").
The same noun right after a determiner ("the system", "this system") is slightly
negative. A Chinese character that follows a Chinese character is positive too,
since Chinese compounds work the same way. Everything else is near zero.

Why this rule: the activation is dense and spread over thousands of words, and
little of it is explained by simple rules. The values below are least-squares fits
on training text. They explain about 2% of the variance on eval, with correlation
r = 0.14. A per-token lookup table would explain more, about 8%, but it is a list
of arbitrary words, so it is not used here.
"""

import regex
import wordnet

READS = ()

# Words that open a noun phrase with no modifier noun before its head.
DETERMINERS = {
    "the", "a", "an", "this", "that", "these", "those", "his", "her", "their",
    "its", "our", "your", "my", "each", "every", "some", "any", "no",
}


def is_word(token):
    word = token.strip().lower()
    return word.isascii() and word.isalpha()


def is_noun(token):
    return is_word(token) and "noun" in wordnet.parts_of_speech(token.strip().lower())


def is_adjective(token):
    return is_word(token) and "adjective" in wordnet.parts_of_speech(token.strip().lower())


def is_han(token):
    return bool(regex.fullmatch(r"\p{Han}", token.strip()))


def step(carry, prefix, upstream):
    # The first token of a document has no modifier before it: predict 0.
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    cur, prev = prefix.token_strings[-1], prefix.token_strings[-2]
    if is_han(cur):
        return carry, 0.31 if is_han(prev) else 0.15
    if cur.startswith(" ") and is_noun(cur):
        if prev.strip().lower() in DETERMINERS:
            return carry, -0.08
        if is_noun(prev):
            return carry, 0.40
        if is_adjective(prev):
            return carry, 0.14
        return carry, 0.05
    return carry, 0.0

"""Clause-linking words: results and contrasts, and the commas that set them up.

Component layers.15.mlp.down_proj:4507 fires when a main clause is about to
state a result or a contrast. It is strongest on the connective that opens that
clause (", so we", ", therefore it", ", but they", ", ので", ", 所以") and on the
comma that closes an introductory phrase or clause ("Without more context,",
"Since this is a review,", "Based on the type of assignment,"), just before the
main clause starts. Averages in the data: about 3.5 for a result word after a
comma or at a sentence start (6 for the Japanese and Chinese causal words), about
2.1 for a contrast word, about 1.5 for the first comma of a sentence that opens
with an introductory word, about 0.4 for other commas. A sentence-initial
introductory word ("if", "since", "in") is slightly negative. Everything else
gets 0.

The program reads the text token by token and keeps three facts about the
current sentence: its first word, whether a comma has been seen, and the
previous token. It predicts from those alone. It is a rough picture: it explains
under a tenth of the variance, because the component also carries much
context-dependent noise on ordinary tokens (digits, "the", "and", "to") and
because "so" and commas vary with more than these words (for example, a math
context lowers "so").
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

# Words that state a result or a conclusion.
CONCLUDE = {
    "so", "therefore", "thus", "hence", "consequently", "accordingly",
    "所以", "因此", "ので", "なので", "だから", "そのため", "ため",
}
# Japanese and Chinese causal words, which are the strongest.
CAUSAL_CJK = {"所以", "因此", "ので", "なので", "だから", "そのため"}
# Words that set up a contrast.
CONTRAST = {
    "but", "yet", "however", "though", "whereas", "nevertheless", "otherwise",
    "pero", "но", "donc", "nhưng", "但", "但是", "しかし", "けど",
}
# Words that end a sentence-initial phrase right before a result ("As a result,").
RESULT_NOUNS = {"result", "consequence"}
# Words that open an introductory phrase or subordinate clause.
OPENERS = {
    "if", "since", "because", "although", "though", "when", "while", "as", "unless",
    "once", "given", "after", "before", "despite", "without", "due", "by", "with",
    "in", "for", "on", "at", "from", "during", "under", "even", "following", "based",
    "according", "unlike", "compared", "regardless", "upon", "until", "had", "were",
    "should", "having", "being", "owing", "considering", "assuming", "within",
}
BOUNDARIES = {".", "!", "?", "。", "！", "？"}
COMMAS = {",", "，"}


def step(carry, prefix, upstream: Mapping):
    # carry: (first word of the sentence or None, previous token's word, comma seen)
    first, prev, seen_comma = carry if carry is not None else (None, "", False)
    if prefix.position > 0 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        first, prev, seen_comma = None, "", False

    tok = prefix.token_strings[-1]
    w = tok.strip().lower()
    boundary = w in BOUNDARIES or (w == "" and "\n" in tok)
    clause_start = prev in COMMAS or prev in BOUNDARIES or prev == ""

    if w in CONCLUDE:
        value = (6.0 if w in CAUSAL_CJK else 3.5) if clause_start else 2.0
    elif w in CONTRAST:
        value = 2.1
    elif w in COMMAS:
        if prev in CONCLUDE or prev in CONTRAST or prev in RESULT_NOUNS:
            value = 2.0
        elif first in OPENERS and not seen_comma:
            value = 1.5
        else:
            value = 0.4
    elif first is None and w in OPENERS:
        value = -0.2
    else:
        value = 0.0

    if boundary:
        first, prev, seen_comma = None, ".", False
    else:
        if first is None and w:
            first = w
        if w in COMMAS:
            seen_comma = True
        prev = w
    return (first, prev, seen_comma), float(value)

"""Layer 15 MLP down_proj, component 4518: a weak, lexical feature.

The activation is set mostly by the current token, and by its neighbour before it. It is
diffuse: most of its variance is spread over thousands of tokens, so a few concepts explain
only a small share. This program keeps the concepts that carry the most of it. Each value is
the mean the component takes for that kind of token, fitted on training text.

  - "that" as a relative or clause word ("a fruit that can", "so that"): high (1.8). After a
    verb of saying or knowing ("suggest that", "show that") it is low (0.5).
  - "at" and "it": high (1.7), except "look at" (0.1).
  - opening brackets and braces in code ("[", "{", "({", "){"): high (2.6).
  - short technical verb stems used as code or API words (get, set, cast, cut, base, data,
    date, test, let, load, record, ...): high (2.7).
  - the digits 5, 4 and 3 (inside numbers): 1.2, 0.7, 0.2.
  - " the" after a verb of getting or finding ("get the", "find the", "calculate the"): 1.0;
    after a preposition ("in the", "during the"): -0.2.
  - a comma after a discourse word ("Yes,", "However,", "Thus,"): -0.7; other commas: -0.35.
  - prepositions and copulas ("of", "on", "for", "is", "an", "by", "with"): -0.3.
  - everything else: the mean, 0.25.
"""

READS = ()

MEAN = 0.25
SAYING = {"suggest", "suggests", "suggested", "show", "showed", "shown", "indicate", "indicated",
          "indicates", "mean", "means", "note", "state", "states", "stated", "say", "said", "says",
          "reveal", "revealed", "suppose", "remember", "understand", "think", "know", "believe",
          "hope", "found", "ensure"}
GET_FIND = {"get", "set", "find", "determine", "calculate", "obtain", "make", "have", "compute",
            "complete", "reach", "use", "take", "got"}
PREPS = {"in", "during", "through", "via", "among", "throughout", "along", "on", "when", "under",
         "than", "over", "from", "for", "of", "by", "with", "as", "at", "before", "after"}
DISCOURSE = {"Yes", "Hmm", "Now", "However", "Thus", "Also", "Therefore", "Furthermore", "Well",
             "So", "Oh", "Again", "Then", "Still", "Hence"}
CODE_BRACKETS = {"[", " [", "{", " {", "({", " ({", "){", "([", " ([", "(d"}
TECH_WORDS = {"get", "set", "cast", "cut", "base", "based", "data", "date", "test", "let", "load",
              "record", "post", "lead", "led", "built", "located", "defined", "limited", "detect",
              "protect"}
DIGITS = {"5": 1.2, "4": 0.7, "3": 0.2}
FUNCTION_WORDS = {" of", " on", " for", " is", " an", " are", " as", " by", " with", " in"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    same_doc = prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip() if same_doc else ""
    if tok == " that":
        return carry, (0.5 if prev in SAYING else 1.8)
    if tok in (" at", " it"):
        return carry, (0.1 if prev in ("look", "looking") else 1.7)
    if tok in CODE_BRACKETS:
        return carry, 2.6
    if tok.strip().lower() in TECH_WORDS and tok[:1] in (" ", ""):
        return carry, 2.7
    if tok in DIGITS:
        return carry, DIGITS[tok]
    if tok == " the":
        if prev in GET_FIND:
            return carry, 1.0
        return carry, (-0.2 if prev in PREPS else 0.1)
    if tok == ",":
        if prev in DISCOURSE:
            return carry, -0.7
        return carry, (-0.3 if prev.isdigit() else -0.35)
    if tok in FUNCTION_WORDS:
        return carry, -0.3
    return carry, MEAN

"""Loop counters in code: component 4542 of layers.15.mlp.down_proj.

The component is a loop-counter detector for C-like code. It is strongest on the
counter variable (i, j, k, n, idx, index, ...) inside a C-style for header
`for (init; test; update)`, and on the number and "=" that start it, so
`for (int i = 0; i < n; i++)` lights up on the i (highest in i++), the 0, and the =.
Outside such headers it is weaker: a counter being declared (`int i`), a counter
after a bracket or paren (`a[i`, `(i`), a space-led " i" or " j" in code, and
`i = 0` / `i = 1` assignments. Prose, numbers in data and other tokens are near zero.

The program tracks, per position, whether it is inside a for header and which
clause (0 init, 1 test, 2 update) it is in, and the previous tokens. It then returns
the typical activation for that kind of token. Values are the group means measured
on training rows, not fitted to eval.
"""
import re

READS = ()

COUNTERS = {"i", "j", "k", "l", "m", "n", "x", "a", "idx", "index", "indices", "ix", "pos", "position", "row", "col"}
DECLARERS = {"int", "let", "var", "long", "size_t"}

COUNTER_IN_HEADER = (15.0, 9.0, 21.0)  # a counter in a for header's init, test and update clauses
START_ZERO = 20.0                      # "0" starting a counter in a for header's init clause
START_OTHER = 4.0                      # any other number in the init clause
INIT_EQUALS = 8.0                      # "=" in the init clause
TEST_END = 5.0                         # ";" ending the test clause
OTHER_HEADER = 1.8                     # any other token inside a for header
DECLARED = 5.7                         # a counter being declared outside a header (int i)
BRACKETED = 1.5                        # a counter right after "[" or "(" outside a header
SPACED_IJ = 2.7                        # " i" or " j" outside a header
OTHER_COUNTER = 0.3                    # any other counter outside a header
ZERO_ASSIGNED = 3.9                    # "0" in "i = 0" outside a header
ONE_ASSIGNED = 1.7                     # "1" in "i = 1" outside a header


def step(carry, prefix, upstream):
    state = dict(carry) if carry else {
        "in_header": False, "depth": 0, "clause": 0, "after_for": False, "prev": "", "prev2": "",
    }
    raw = prefix.token_strings[-1]
    tok = raw.strip()
    name = re.sub(r"^[\W_]+", "", tok)
    clause = min(state["clause"], 2)
    value = 0.0
    if state["in_header"]:
        if name in COUNTERS:
            value = COUNTER_IN_HEADER[clause]
        elif tok == "0" and clause == 0:
            value = START_ZERO
        elif re.fullmatch(r"\d+", tok):
            value = START_OTHER if clause == 0 else OTHER_HEADER
        elif tok == "=" and clause == 0:
            value = INIT_EQUALS
        elif tok == ";" and clause == 1:
            value = TEST_END
        else:
            value = OTHER_HEADER
    elif name in COUNTERS:
        if state["prev"] in DECLARERS:
            value = DECLARED
        elif raw[:1] in "[(":
            value = BRACKETED
        elif tok in ("i", "j"):
            value = SPACED_IJ if raw[:1] == " " else OTHER_COUNTER
        else:
            value = OTHER_COUNTER
    elif tok in ("0", "1") and state["prev"] == "=" and re.sub(r"^[\W_]+", "", state["prev2"]) in COUNTERS:
        value = ZERO_ASSIGNED if tok == "0" else ONE_ASSIGNED
    # Track the for header: "for" then "(" opens it, matching ")" closes it, ";" at depth 1 ends a clause.
    for ch in tok:
        if state["in_header"]:
            if ch == "(":
                state["depth"] += 1
            elif ch == ")":
                state["depth"] -= 1
                if state["depth"] == 0:
                    state["in_header"] = False
            elif ch == ";" and state["depth"] == 1:
                state["clause"] += 1
        elif state["after_for"] and ch == "(":
            state["in_header"], state["depth"], state["clause"] = True, 1, 0
        state["after_for"] = (tok == "for" and ch == "r") or (state["after_for"] and ch == " ")
    state["prev2"], state["prev"] = state["prev"], tok
    return state, value
